BEGIN;
UPDATE recipes r SET allergens=COALESCE(a.allergens,''),updated_at=now() FROM (SELECT r.id,string_agg(DISTINCT trim(code),',' ORDER BY trim(code)) allergens FROM recipes r JOIN recipe_ingredients ri ON ri.recipe_id=r.id AND NOT ri.is_deleted JOIN ingredients i ON i.id=ri.ingredient_id AND NOT i.is_deleted CROSS JOIN LATERAL regexp_split_to_table(COALESCE(i.allergens,''), '[,;]') code WHERE r.source_type='production-catalog-v1' AND NOT r.is_deleted AND trim(code)<>'' GROUP BY r.id) a WHERE a.id=r.id;
COMMIT;
SELECT count(*) FROM recipes WHERE source_type='production-catalog-v1' AND NOT is_deleted;
