INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Cơm gà xào cải ngọt'),2,31))::uuid,now(),false,'Cơm gà xào cải ngọt','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Cơm trắng, Ức gà, Cải ngọt. Định lượng cho 2 khẩu phần.','',25,'easy',2,'1. Rửa sạch, để ráo và cắt các nguyên liệu thành miếng vừa ăn; để riêng đạm và rau. 2. Làm nóng dầu, phi thơm hành hoặc tỏi nếu có; xào phần đạm đến khi chín. 3. Cho rau củ vào, đảo nhanh ở lửa vừa-lớn để rau vừa chín; nêm với gia vị đã định lượng. 4. Kiểm tra độ chín của đạm, bày ra đĩa và dùng nóng. 5. Nếu có cơm chín trong danh sách, làm nóng cơm riêng trước khi dùng; không tính lượng cơm đã nấu như gạo khô.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Cơm gà xào cải ngọt' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Cơm gà áp chảo bông cải'),2,31))::uuid,now(),false,'Cơm gà áp chảo bông cải','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Cơm gạo lứt, Ức gà, Bông cải xanh. Định lượng cho 2 khẩu phần.','',30,'easy',2,'1. Sơ chế, thấm khô nguyên liệu chính; ướp nhẹ với gia vị trong công thức. 2. Làm nóng chảo cùng dầu, áp chảo từng mặt đến khi chín phù hợp; tránh để quá lửa. 3. Làm chín rau củ ăn kèm trên chảo hoặc hấp riêng. 4. Rưới phần sốt hoặc nước cốt chanh nếu có, chia đều theo khẩu phần. 5. Nếu có cơm chín trong danh sách, làm nóng cơm riêng trước khi dùng; không tính lượng cơm đã nấu như gạo khô.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Cơm gà áp chảo bông cải' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Cơm bò xào hành tây'),2,31))::uuid,now(),false,'Cơm bò xào hành tây','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Cơm trắng, Thịt bò thăn, Hành tây. Định lượng cho 2 khẩu phần.','',25,'easy',2,'1. Rửa sạch, để ráo và cắt các nguyên liệu thành miếng vừa ăn; để riêng đạm và rau. 2. Làm nóng dầu, phi thơm hành hoặc tỏi nếu có; xào phần đạm đến khi chín. 3. Cho rau củ vào, đảo nhanh ở lửa vừa-lớn để rau vừa chín; nêm với gia vị đã định lượng. 4. Kiểm tra độ chín của đạm, bày ra đĩa và dùng nóng. 5. Nếu có cơm chín trong danh sách, làm nóng cơm riêng trước khi dùng; không tính lượng cơm đã nấu như gạo khô.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Cơm bò xào hành tây' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Cơm tôm xào đậu Hà Lan'),2,31))::uuid,now(),false,'Cơm tôm xào đậu Hà Lan','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Cơm trắng, Tôm thẻ, Đậu Hà Lan. Định lượng cho 2 khẩu phần.','',25,'easy',2,'1. Rửa sạch, để ráo và cắt các nguyên liệu thành miếng vừa ăn; để riêng đạm và rau. 2. Làm nóng dầu, phi thơm hành hoặc tỏi nếu có; xào phần đạm đến khi chín. 3. Cho rau củ vào, đảo nhanh ở lửa vừa-lớn để rau vừa chín; nêm với gia vị đã định lượng. 4. Kiểm tra độ chín của đạm, bày ra đĩa và dùng nóng. 5. Nếu có cơm chín trong danh sách, làm nóng cơm riêng trước khi dùng; không tính lượng cơm đã nấu như gạo khô.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Cơm tôm xào đậu Hà Lan' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Cơm cá hồi áp chảo'),2,31))::uuid,now(),false,'Cơm cá hồi áp chảo','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Cơm gạo lứt, Cá hồi, Măng tây. Định lượng cho 2 khẩu phần.','',30,'medium',2,'1. Sơ chế, thấm khô nguyên liệu chính; ướp nhẹ với gia vị trong công thức. 2. Làm nóng chảo cùng dầu, áp chảo từng mặt đến khi chín phù hợp; tránh để quá lửa. 3. Làm chín rau củ ăn kèm trên chảo hoặc hấp riêng. 4. Rưới phần sốt hoặc nước cốt chanh nếu có, chia đều theo khẩu phần. 5. Nếu có cơm chín trong danh sách, làm nóng cơm riêng trước khi dùng; không tính lượng cơm đã nấu như gạo khô.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Cơm cá hồi áp chảo' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Cơm trứng chiên cà chua'),2,31))::uuid,now(),false,'Cơm trứng chiên cà chua','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Cơm trắng, Trứng gà, Cà chua. Định lượng cho 2 khẩu phần.','',20,'easy',2,'1. Sơ chế và cắt nhỏ phần nguyên liệu cần thiết. 2. Làm nóng lượng dầu trong công thức; chiên nguyên liệu chính từng mẻ đến khi chín và có màu vàng vừa. 3. Với cơm hoặc rau kèm, đảo đều trên chảo và nêm gia vị; với cá, để ráo dầu trước khi dùng. 4. Dùng nóng, kiểm tra kỹ độ chín đối với trứng và hải sản. 5. Nếu có cơm chín trong danh sách, làm nóng cơm riêng trước khi dùng; không tính lượng cơm đã nấu như gạo khô.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Cơm trứng chiên cà chua' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Cơm đậu hũ sốt nấm'),2,31))::uuid,now(),false,'Cơm đậu hũ sốt nấm','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Cơm gạo lứt, Đậu hũ trắng, Nấm mỡ. Định lượng cho 2 khẩu phần.','',25,'easy',2,'1. Rửa sạch, thái hoặc cắt nguyên liệu theo kích thước vừa ăn. 2. Làm chín phần đạm trước trên chảo; lấy ra riêng nếu cần. 3. Xào thơm hành, tỏi rồi đun cà chua, nấm hoặc thành phần tạo sốt đến khi mềm; thêm ít nước nếu quá đặc. 4. Cho nguyên liệu chính trở lại, nấu đến khi chín hoàn toàn và sốt bám đều. 5. Nếu có cơm chín trong danh sách, làm nóng cơm riêng trước khi dùng; không tính lượng cơm đã nấu như gạo khô.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Cơm đậu hũ sốt nấm' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Cơm gà xé rau củ'),2,31))::uuid,now(),false,'Cơm gà xé rau củ','Món trộn hoặc cuốn với các thành phần tươi, thích hợp thay đổi thực đơn hằng ngày; thành phần chính gồm Cơm trắng, Thịt gà xé chín, Cà rốt. Định lượng cho 2 khẩu phần.','',20,'easy',2,'1. Rửa sạch và để ráo rau quả; nấu chín phần thịt, cá, trứng hoặc ngũ cốc chưa chín trong công thức, để nguội vừa. 2. Cắt các thành phần thành miếng vừa ăn. 3. Đánh đều dầu ô liu, chanh hoặc giấm, sữa chua cùng gia vị theo danh sách. 4. Trộn đều trước khi dùng, bảo quản lạnh nếu chưa ăn ngay.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Cơm gà xé rau củ' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Cơm tấm sườn áp chảo'),2,31))::uuid,now(),false,'Cơm tấm sườn áp chảo','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Cơm trắng, Sườn heo, Dưa leo. Định lượng cho 2 khẩu phần.','',35,'medium',2,'1. Sơ chế, thấm khô nguyên liệu chính; ướp nhẹ với gia vị trong công thức. 2. Làm nóng chảo cùng dầu, áp chảo từng mặt đến khi chín phù hợp; tránh để quá lửa. 3. Làm chín rau củ ăn kèm trên chảo hoặc hấp riêng. 4. Rưới phần sốt hoặc nước cốt chanh nếu có, chia đều theo khẩu phần. 5. Nếu có cơm chín trong danh sách, làm nóng cơm riêng trước khi dùng; không tính lượng cơm đã nấu như gạo khô.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Cơm tấm sườn áp chảo' AND NOT r.is_deleted);
