INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Cơm chiên trứng rau củ'),2,31))::uuid,now(),false,'Cơm chiên trứng rau củ','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Cơm trắng, Trứng gà, Cà rốt. Định lượng cho 2 khẩu phần.','',20,'easy',2,'1. Sơ chế và cắt nhỏ phần nguyên liệu cần thiết. 2. Làm nóng lượng dầu trong công thức; chiên nguyên liệu chính từng mẻ đến khi chín và có màu vàng vừa. 3. Với cơm hoặc rau kèm, đảo đều trên chảo và nêm gia vị; với cá, để ráo dầu trước khi dùng. 4. Dùng nóng, kiểm tra kỹ độ chín đối với trứng và hải sản. 5. Nếu có cơm chín trong danh sách, làm nóng cơm riêng trước khi dùng; không tính lượng cơm đã nấu như gạo khô.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Cơm chiên trứng rau củ' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Cơm chiên hải sản'),2,31))::uuid,now(),false,'Cơm chiên hải sản','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Cơm trắng, Tôm thẻ, Mực ống. Định lượng cho 2 khẩu phần.','',25,'medium',2,'1. Sơ chế và cắt nhỏ phần nguyên liệu cần thiết. 2. Làm nóng lượng dầu trong công thức; chiên nguyên liệu chính từng mẻ đến khi chín và có màu vàng vừa. 3. Với cơm hoặc rau kèm, đảo đều trên chảo và nêm gia vị; với cá, để ráo dầu trước khi dùng. 4. Dùng nóng, kiểm tra kỹ độ chín đối với trứng và hải sản. 5. Nếu có cơm chín trong danh sách, làm nóng cơm riêng trước khi dùng; không tính lượng cơm đã nấu như gạo khô.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Cơm chiên hải sản' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Cơm gà nướng sả'),2,31))::uuid,now(),false,'Cơm gà nướng sả','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Cơm trắng, Đùi gà có da. Định lượng cho 2 khẩu phần.','',40,'medium',2,'1. Sơ chế nguyên liệu, ướp với phần gia vị có trong công thức khoảng 10–15 phút. 2. Làm nóng lò ở khoảng 190°C hoặc chuẩn bị nồi chiên không dầu; đặt thực phẩm lên khay. 3. Nướng đến khi chín, lật hoặc đảo giữa chừng nếu cần, điều chỉnh thời gian theo kích thước thực tế. 4. Kiểm tra thịt gia cầm chín hoàn toàn, bày cùng phần rau đi kèm. 5. Nếu có cơm chín trong danh sách, làm nóng cơm riêng trước khi dùng; không tính lượng cơm đã nấu như gạo khô.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Cơm gà nướng sả' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Cơm heo kho trứng'),2,31))::uuid,now(),false,'Cơm heo kho trứng','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Cơm trắng, Thịt heo nạc vai, Trứng gà. Định lượng cho 2 khẩu phần.','',50,'medium',2,'1. Rửa sạch, sơ chế nguyên liệu; ướp cùng hành, nước mắm hoặc gia vị trong 10–15 phút. 2. Làm nóng nồi, đảo săn nguyên liệu chính. 3. Thêm lượng nước hoặc nước dừa đã liệt kê nếu có; đậy nắp, kho lửa nhỏ đến khi chín mềm và nước sệt vừa. 4. Nếm lại trước khi dùng; món kho thịt phải chín kỹ. 5. Nếu có cơm chín trong danh sách, làm nóng cơm riêng trước khi dùng; không tính lượng cơm đã nấu như gạo khô.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Cơm heo kho trứng' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Cơm đậu gà cà ri'),2,31))::uuid,now(),false,'Cơm đậu gà cà ri','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Cơm gạo lứt, Đậu gà nấu chín, Cà chua. Định lượng cho 2 khẩu phần.','',35,'easy',2,'1. Sơ chế nguyên liệu, cắt thịt hoặc khoai thành miếng vừa. 2. Phi thơm hành và bột cà ri cùng ít dầu, đảo nguyên liệu chính cho săn. 3. Thêm nước cốt dừa và nước vừa đủ, nấu lửa nhỏ cho đến khi các thành phần chín mềm. 4. Nêm lại, chia đều theo khẩu phần, ăn cùng cơm nếu có trong định lượng. 5. Nếu có cơm chín trong danh sách, làm nóng cơm riêng trước khi dùng; không tính lượng cơm đã nấu như gạo khô.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Cơm đậu gà cà ri' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Cơm thịt bò xào cần tây'),2,31))::uuid,now(),false,'Cơm thịt bò xào cần tây','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Cơm trắng, Thịt bò bắp, Cần tây. Định lượng cho 2 khẩu phần.','',25,'easy',2,'1. Rửa sạch, để ráo và cắt các nguyên liệu thành miếng vừa ăn; để riêng đạm và rau. 2. Làm nóng dầu, phi thơm hành hoặc tỏi nếu có; xào phần đạm đến khi chín. 3. Cho rau củ vào, đảo nhanh ở lửa vừa-lớn để rau vừa chín; nêm với gia vị đã định lượng. 4. Kiểm tra độ chín của đạm, bày ra đĩa và dùng nóng. 5. Nếu có cơm chín trong danh sách, làm nóng cơm riêng trước khi dùng; không tính lượng cơm đã nấu như gạo khô.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Cơm thịt bò xào cần tây' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Cơm lứt cá basa sốt gừng'),2,31))::uuid,now(),false,'Cơm lứt cá basa sốt gừng','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Cơm gạo lứt, Cá basa. Định lượng cho 2 khẩu phần.','',30,'easy',2,'1. Rửa sạch, thái hoặc cắt nguyên liệu theo kích thước vừa ăn. 2. Làm chín phần đạm trước trên chảo; lấy ra riêng nếu cần. 3. Xào thơm hành, tỏi rồi đun cà chua, nấm hoặc thành phần tạo sốt đến khi mềm; thêm ít nước nếu quá đặc. 4. Cho nguyên liệu chính trở lại, nấu đến khi chín hoàn toàn và sốt bám đều. 5. Nếu có cơm chín trong danh sách, làm nóng cơm riêng trước khi dùng; không tính lượng cơm đã nấu như gạo khô.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Cơm lứt cá basa sốt gừng' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Gà hấp gừng hành'),2,31))::uuid,now(),false,'Gà hấp gừng hành','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Gà nguyên con. Định lượng cho 3 khẩu phần.','',40,'medium',3,'1. Làm sạch và sơ chế nguyên liệu; trải gia vị thơm như gừng, sả hoặc hành nếu có. 2. Đun sôi nước trong xửng hấp, đặt thực phẩm vào đĩa chịu nhiệt. 3. Hấp đến khi nguyên liệu chín hoàn toàn; hải sản vừa chín tới, thịt gia cầm không còn phần sống. 4. Pha phần nước chấm từ gia vị có sẵn và dùng nóng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Gà hấp gừng hành' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Gà kho sả ớt'),2,31))::uuid,now(),false,'Gà kho sả ớt','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Đùi gà bỏ da. Định lượng cho 3 khẩu phần.','',40,'easy',3,'1. Rửa sạch, sơ chế nguyên liệu; ướp cùng hành, nước mắm hoặc gia vị trong 10–15 phút. 2. Làm nóng nồi, đảo săn nguyên liệu chính. 3. Thêm lượng nước hoặc nước dừa đã liệt kê nếu có; đậy nắp, kho lửa nhỏ đến khi chín mềm và nước sệt vừa. 4. Nếm lại trước khi dùng; món kho thịt phải chín kỹ.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Gà kho sả ớt' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Gà xào nấm hương'),2,31))::uuid,now(),false,'Gà xào nấm hương','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Ức gà, Nấm hương tươi, Cà rốt. Định lượng cho 2 khẩu phần.','',25,'easy',2,'1. Rửa sạch, để ráo và cắt các nguyên liệu thành miếng vừa ăn; để riêng đạm và rau. 2. Làm nóng dầu, phi thơm hành hoặc tỏi nếu có; xào phần đạm đến khi chín. 3. Cho rau củ vào, đảo nhanh ở lửa vừa-lớn để rau vừa chín; nêm với gia vị đã định lượng. 4. Kiểm tra độ chín của đạm, bày ra đĩa và dùng nóng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Gà xào nấm hương' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Gà áp chảo sốt tiêu đen'),2,31))::uuid,now(),false,'Gà áp chảo sốt tiêu đen','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Ức gà, Hành tây. Định lượng cho 2 khẩu phần.','',30,'easy',2,'1. Sơ chế, thấm khô nguyên liệu chính; ướp nhẹ với gia vị trong công thức. 2. Làm nóng chảo cùng dầu, áp chảo từng mặt đến khi chín phù hợp; tránh để quá lửa. 3. Làm chín rau củ ăn kèm trên chảo hoặc hấp riêng. 4. Rưới phần sốt hoặc nước cốt chanh nếu có, chia đều theo khẩu phần.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Gà áp chảo sốt tiêu đen' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Gà nướng mật ong'),2,31))::uuid,now(),false,'Gà nướng mật ong','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Đùi gà có da. Định lượng cho 3 khẩu phần.','',45,'medium',3,'1. Sơ chế nguyên liệu, ướp với phần gia vị có trong công thức khoảng 10–15 phút. 2. Làm nóng lò ở khoảng 190°C hoặc chuẩn bị nồi chiên không dầu; đặt thực phẩm lên khay. 3. Nướng đến khi chín, lật hoặc đảo giữa chừng nếu cần, điều chỉnh thời gian theo kích thước thực tế. 4. Kiểm tra thịt gia cầm chín hoàn toàn, bày cùng phần rau đi kèm.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Gà nướng mật ong' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Gà om bí đỏ'),2,31))::uuid,now(),false,'Gà om bí đỏ','Món nước ấm, có thể chia thành các khẩu phần gia đình; thành phần chính gồm Đùi gà bỏ da, Bí đỏ, Cà rốt. Định lượng cho 3 khẩu phần.','',45,'easy',3,'1. Sơ chế nguyên liệu, xử lý và ngâm đậu khô trước nếu cần (thời gian ngâm không tính vào thời gian nấu). 2. Đun phần nước hoặc nước dùng, cho nguyên liệu lâu chín vào trước. 3. Hầm lửa nhỏ cho đến khi thịt hoặc đậu mềm, tiếp đó thêm rau củ để tránh nát. 4. Nêm gia vị và chia khẩu phần khi còn nóng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Gà om bí đỏ' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Gà cuộn cải bó xôi'),2,31))::uuid,now(),false,'Gà cuộn cải bó xôi','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Ức gà, Cải bó xôi, Phô mai mozzarella. Định lượng cho 2 khẩu phần.','',35,'medium',2,'1. Sơ chế, thấm khô nguyên liệu chính; ướp nhẹ với gia vị trong công thức. 2. Làm nóng chảo cùng dầu, áp chảo từng mặt đến khi chín phù hợp; tránh để quá lửa. 3. Làm chín rau củ ăn kèm trên chảo hoặc hấp riêng. 4. Rưới phần sốt hoặc nước cốt chanh nếu có, chia đều theo khẩu phần.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Gà cuộn cải bó xôi' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Gà xào hạt điều'),2,31))::uuid,now(),false,'Gà xào hạt điều','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Ức gà, Hạt điều, Ớt chuông đỏ. Định lượng cho 2 khẩu phần.','',30,'medium',2,'1. Rửa sạch, để ráo và cắt các nguyên liệu thành miếng vừa ăn; để riêng đạm và rau. 2. Làm nóng dầu, phi thơm hành hoặc tỏi nếu có; xào phần đạm đến khi chín. 3. Cho rau củ vào, đảo nhanh ở lửa vừa-lớn để rau vừa chín; nêm với gia vị đã định lượng. 4. Kiểm tra độ chín của đạm, bày ra đĩa và dùng nóng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Gà xào hạt điều' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Gà nướng lá chanh'),2,31))::uuid,now(),false,'Gà nướng lá chanh','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Đùi gà có da. Định lượng cho 3 khẩu phần.','',45,'medium',3,'1. Sơ chế nguyên liệu, ướp với phần gia vị có trong công thức khoảng 10–15 phút. 2. Làm nóng lò ở khoảng 190°C hoặc chuẩn bị nồi chiên không dầu; đặt thực phẩm lên khay. 3. Nướng đến khi chín, lật hoặc đảo giữa chừng nếu cần, điều chỉnh thời gian theo kích thước thực tế. 4. Kiểm tra thịt gia cầm chín hoàn toàn, bày cùng phần rau đi kèm.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Gà nướng lá chanh' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Gà sốt sữa chua'),2,31))::uuid,now(),false,'Gà sốt sữa chua','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Ức gà, Sữa chua không đường, Chanh vàng. Định lượng cho 2 khẩu phần.','',30,'easy',2,'1. Sơ chế, thấm khô nguyên liệu chính; ướp nhẹ với gia vị trong công thức. 2. Làm nóng chảo cùng dầu, áp chảo từng mặt đến khi chín phù hợp; tránh để quá lửa. 3. Làm chín rau củ ăn kèm trên chảo hoặc hấp riêng. 4. Rưới phần sốt hoặc nước cốt chanh nếu có, chia đều theo khẩu phần.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Gà sốt sữa chua' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Gà nấu cà ri nước cốt dừa'),2,31))::uuid,now(),false,'Gà nấu cà ri nước cốt dừa','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Đùi gà bỏ da, Khoai tây, Cà rốt. Định lượng cho 3 khẩu phần.','',45,'medium',3,'1. Sơ chế nguyên liệu, cắt thịt hoặc khoai thành miếng vừa. 2. Phi thơm hành và bột cà ri cùng ít dầu, đảo nguyên liệu chính cho săn. 3. Thêm nước cốt dừa và nước vừa đủ, nấu lửa nhỏ cho đến khi các thành phần chín mềm. 4. Nêm lại, chia đều theo khẩu phần, ăn cùng cơm nếu có trong định lượng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Gà nấu cà ri nước cốt dừa' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Gà xào cải thìa'),2,31))::uuid,now(),false,'Gà xào cải thìa','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Ức gà, Cải thìa, Nấm mỡ. Định lượng cho 2 khẩu phần.','',25,'easy',2,'1. Rửa sạch, để ráo và cắt các nguyên liệu thành miếng vừa ăn; để riêng đạm và rau. 2. Làm nóng dầu, phi thơm hành hoặc tỏi nếu có; xào phần đạm đến khi chín. 3. Cho rau củ vào, đảo nhanh ở lửa vừa-lớn để rau vừa chín; nêm với gia vị đã định lượng. 4. Kiểm tra độ chín của đạm, bày ra đĩa và dùng nóng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Gà xào cải thìa' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Gà kho gừng'),2,31))::uuid,now(),false,'Gà kho gừng','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Đùi gà bỏ da. Định lượng cho 3 khẩu phần.','',40,'easy',3,'1. Rửa sạch, sơ chế nguyên liệu; ướp cùng hành, nước mắm hoặc gia vị trong 10–15 phút. 2. Làm nóng nồi, đảo săn nguyên liệu chính. 3. Thêm lượng nước hoặc nước dừa đã liệt kê nếu có; đậy nắp, kho lửa nhỏ đến khi chín mềm và nước sệt vừa. 4. Nếm lại trước khi dùng; món kho thịt phải chín kỹ.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Gà kho gừng' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Gà hầm hạt sen'),2,31))::uuid,now(),false,'Gà hầm hạt sen','Món nước ấm, có thể chia thành các khẩu phần gia đình; thành phần chính gồm Gà nguyên con, Hạt sen tươi, Cà rốt. Định lượng cho 3 khẩu phần.','',55,'medium',3,'1. Sơ chế nguyên liệu, xử lý và ngâm đậu khô trước nếu cần (thời gian ngâm không tính vào thời gian nấu). 2. Đun phần nước hoặc nước dùng, cho nguyên liệu lâu chín vào trước. 3. Hầm lửa nhỏ cho đến khi thịt hoặc đậu mềm, tiếp đó thêm rau củ để tránh nát. 4. Nêm gia vị và chia khẩu phần khi còn nóng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Gà hầm hạt sen' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Gà cuốn bánh tráng rau sống'),2,31))::uuid,now(),false,'Gà cuốn bánh tráng rau sống','Món trộn hoặc cuốn với các thành phần tươi, thích hợp thay đổi thực đơn hằng ngày; thành phần chính gồm Thịt gà xé chín, Bánh tráng gạo, Rau xà lách. Định lượng cho 2 khẩu phần.','',25,'easy',2,'1. Luộc hoặc hấp chín phần thịt, tôm chưa chín; rửa sạch rau ăn sống và để ráo. 2. Làm mềm bánh tráng theo hướng dẫn trên bao bì. 3. Đặt lượng nhân vừa phải, cuốn chặt tay; tránh để cuốn quá lâu làm bánh mềm nhũn. 4. Pha nước chấm từ thành phần đã cho, ăn ngay sau khi cuốn.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Gà cuốn bánh tráng rau sống' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Thịt heo kho tiêu'),2,31))::uuid,now(),false,'Thịt heo kho tiêu','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Thịt heo nạc vai. Định lượng cho 3 khẩu phần.','',40,'easy',3,'1. Rửa sạch, sơ chế nguyên liệu; ướp cùng hành, nước mắm hoặc gia vị trong 10–15 phút. 2. Làm nóng nồi, đảo săn nguyên liệu chính. 3. Thêm lượng nước hoặc nước dừa đã liệt kê nếu có; đậy nắp, kho lửa nhỏ đến khi chín mềm và nước sệt vừa. 4. Nếm lại trước khi dùng; món kho thịt phải chín kỹ.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Thịt heo kho tiêu' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Thịt ba chỉ rang cháy cạnh'),2,31))::uuid,now(),false,'Thịt ba chỉ rang cháy cạnh','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Thịt heo ba chỉ. Định lượng cho 3 khẩu phần.','',30,'medium',3,'1. Cắt nguyên liệu chính thành miếng vừa ăn, để ráo. 2. Cho vào chảo nóng, đảo cho phần thịt săn và ra bớt mỡ; chỉ thêm dầu khi cần. 3. Cho hành, gia vị và rang ở lửa vừa đến khi thịt chín, màu đẹp. 4. Nếm lại và dùng nóng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Thịt ba chỉ rang cháy cạnh' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Sườn non rim mặn ngọt'),2,31))::uuid,now(),false,'Sườn non rim mặn ngọt','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Sườn non heo. Định lượng cho 3 khẩu phần.','',45,'medium',3,'1. Sơ chế và để ráo nguyên liệu chính. 2. Hòa phần nước mắm, đường, me hoặc mật ong nếu có thành hỗn hợp sốt. 3. Áp chảo nhanh nguyên liệu, thêm sốt rồi rim lửa nhỏ, đảo nhẹ để sốt áo đều đến khi chín. 4. Tắt bếp khi nước sốt sánh vừa, dùng nóng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Sườn non rim mặn ngọt' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Thịt heo viên sốt cà'),2,31))::uuid,now(),false,'Thịt heo viên sốt cà','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Thịt heo xay, Cà chua, Hành tây. Định lượng cho 3 khẩu phần.','',35,'medium',3,'1. Rửa sạch, thái hoặc cắt nguyên liệu theo kích thước vừa ăn. 2. Làm chín phần đạm trước trên chảo; lấy ra riêng nếu cần. 3. Xào thơm hành, tỏi rồi đun cà chua, nấm hoặc thành phần tạo sốt đến khi mềm; thêm ít nước nếu quá đặc. 4. Cho nguyên liệu chính trở lại, nấu đến khi chín hoàn toàn và sốt bám đều.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Thịt heo viên sốt cà' AND NOT r.is_deleted);
