INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Thịt bò kho cà rốt'),2,31))::uuid,now(),false,'Thịt bò kho cà rốt','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Thịt bò bắp, Cà rốt. Định lượng cho 4 khẩu phần.','',90,'hard',4,'1. Rửa sạch, sơ chế nguyên liệu; ướp cùng hành, nước mắm hoặc gia vị trong 10–15 phút. 2. Làm nóng nồi, đảo săn nguyên liệu chính. 3. Thêm lượng nước hoặc nước dừa đã liệt kê nếu có; đậy nắp, kho lửa nhỏ đến khi chín mềm và nước sệt vừa. 4. Nếm lại trước khi dùng; món kho thịt phải chín kỹ.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Thịt bò kho cà rốt' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Thịt bò sốt nấm tiêu'),2,31))::uuid,now(),false,'Thịt bò sốt nấm tiêu','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Thịt bò phi lê, Nấm mỡ, Hành tây. Định lượng cho 2 khẩu phần.','',35,'medium',2,'1. Rửa sạch, thái hoặc cắt nguyên liệu theo kích thước vừa ăn. 2. Làm chín phần đạm trước trên chảo; lấy ra riêng nếu cần. 3. Xào thơm hành, tỏi rồi đun cà chua, nấm hoặc thành phần tạo sốt đến khi mềm; thêm ít nước nếu quá đặc. 4. Cho nguyên liệu chính trở lại, nấu đến khi chín hoàn toàn và sốt bám đều.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Thịt bò sốt nấm tiêu' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Thịt bò áp chảo tỏi'),2,31))::uuid,now(),false,'Thịt bò áp chảo tỏi','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Thịt bò thăn, Măng tây. Định lượng cho 2 khẩu phần.','',25,'easy',2,'1. Sơ chế, thấm khô nguyên liệu chính; ướp nhẹ với gia vị trong công thức. 2. Làm nóng chảo cùng dầu, áp chảo từng mặt đến khi chín phù hợp; tránh để quá lửa. 3. Làm chín rau củ ăn kèm trên chảo hoặc hấp riêng. 4. Rưới phần sốt hoặc nước cốt chanh nếu có, chia đều theo khẩu phần.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Thịt bò áp chảo tỏi' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Thịt bò xào rau muống'),2,31))::uuid,now(),false,'Thịt bò xào rau muống','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Thịt bò thăn, Rau muống. Định lượng cho 2 khẩu phần.','',25,'easy',2,'1. Rửa sạch, để ráo và cắt các nguyên liệu thành miếng vừa ăn; để riêng đạm và rau. 2. Làm nóng dầu, phi thơm hành hoặc tỏi nếu có; xào phần đạm đến khi chín. 3. Cho rau củ vào, đảo nhanh ở lửa vừa-lớn để rau vừa chín; nêm với gia vị đã định lượng. 4. Kiểm tra độ chín của đạm, bày ra đĩa và dùng nóng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Thịt bò xào rau muống' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Bò hầm khoai tây'),2,31))::uuid,now(),false,'Bò hầm khoai tây','Món nước ấm, có thể chia thành các khẩu phần gia đình; thành phần chính gồm Thịt bò bắp, Khoai tây, Cà rốt. Định lượng cho 4 khẩu phần.','',85,'hard',4,'1. Sơ chế nguyên liệu, xử lý và ngâm đậu khô trước nếu cần (thời gian ngâm không tính vào thời gian nấu). 2. Đun phần nước hoặc nước dùng, cho nguyên liệu lâu chín vào trước. 3. Hầm lửa nhỏ cho đến khi thịt hoặc đậu mềm, tiếp đó thêm rau củ để tránh nát. 4. Nêm gia vị và chia khẩu phần khi còn nóng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Bò hầm khoai tây' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Thịt heo nướng sả mật ong'),2,31))::uuid,now(),false,'Thịt heo nướng sả mật ong','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Thịt heo nạc vai. Định lượng cho 3 khẩu phần.','',40,'medium',3,'1. Sơ chế nguyên liệu, ướp với phần gia vị có trong công thức khoảng 10–15 phút. 2. Làm nóng lò ở khoảng 190°C hoặc chuẩn bị nồi chiên không dầu; đặt thực phẩm lên khay. 3. Nướng đến khi chín, lật hoặc đảo giữa chừng nếu cần, điều chỉnh thời gian theo kích thước thực tế. 4. Kiểm tra thịt gia cầm chín hoàn toàn, bày cùng phần rau đi kèm.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Thịt heo nướng sả mật ong' AND NOT r.is_deleted);
