INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Sườn heo nướng mật ong'),2,31))::uuid,now(),false,'Sườn heo nướng mật ong','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Sườn non heo. Định lượng cho 3 khẩu phần.','',55,'medium',3,'1. Sơ chế nguyên liệu, ướp với phần gia vị có trong công thức khoảng 10–15 phút. 2. Làm nóng lò ở khoảng 190°C hoặc chuẩn bị nồi chiên không dầu; đặt thực phẩm lên khay. 3. Nướng đến khi chín, lật hoặc đảo giữa chừng nếu cần, điều chỉnh thời gian theo kích thước thực tế. 4. Kiểm tra thịt gia cầm chín hoàn toàn, bày cùng phần rau đi kèm.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Sườn heo nướng mật ong' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Cá lóc hấp gừng'),2,31))::uuid,now(),false,'Cá lóc hấp gừng','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Cá lóc, Chanh. Định lượng cho 3 khẩu phần.','',35,'easy',3,'1. Làm sạch và sơ chế nguyên liệu; trải gia vị thơm như gừng, sả hoặc hành nếu có. 2. Đun sôi nước trong xửng hấp, đặt thực phẩm vào đĩa chịu nhiệt. 3. Hấp đến khi nguyên liệu chín hoàn toàn; hải sản vừa chín tới, thịt gia cầm không còn phần sống. 4. Pha phần nước chấm từ gia vị có sẵn và dùng nóng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Cá lóc hấp gừng' AND NOT r.is_deleted);
