INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Cá diêu hồng hấp hành'),2,31))::uuid,now(),false,'Cá diêu hồng hấp hành','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Cá diêu hồng. Định lượng cho 3 khẩu phần.','',35,'easy',3,'1. Làm sạch và sơ chế nguyên liệu; trải gia vị thơm như gừng, sả hoặc hành nếu có. 2. Đun sôi nước trong xửng hấp, đặt thực phẩm vào đĩa chịu nhiệt. 3. Hấp đến khi nguyên liệu chín hoàn toàn; hải sản vừa chín tới, thịt gia cầm không còn phần sống. 4. Pha phần nước chấm từ gia vị có sẵn và dùng nóng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Cá diêu hồng hấp hành' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Cá nục kho cà'),2,31))::uuid,now(),false,'Cá nục kho cà','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Cá nục, Cà chua. Định lượng cho 3 khẩu phần.','',45,'medium',3,'1. Rửa sạch, sơ chế nguyên liệu; ướp cùng hành, nước mắm hoặc gia vị trong 10–15 phút. 2. Làm nóng nồi, đảo săn nguyên liệu chính. 3. Thêm lượng nước hoặc nước dừa đã liệt kê nếu có; đậy nắp, kho lửa nhỏ đến khi chín mềm và nước sệt vừa. 4. Nếm lại trước khi dùng; món kho thịt phải chín kỹ.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Cá nục kho cà' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Tôm rim nước mắm'),2,31))::uuid,now(),false,'Tôm rim nước mắm','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Tôm sú. Định lượng cho 3 khẩu phần.','',25,'easy',3,'1. Sơ chế và để ráo nguyên liệu chính. 2. Hòa phần nước mắm, đường, me hoặc mật ong nếu có thành hỗn hợp sốt. 3. Áp chảo nhanh nguyên liệu, thêm sốt rồi rim lửa nhỏ, đảo nhẹ để sốt áo đều đến khi chín. 4. Tắt bếp khi nước sốt sánh vừa, dùng nóng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Tôm rim nước mắm' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Tôm hấp sả'),2,31))::uuid,now(),false,'Tôm hấp sả','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Tôm thẻ. Định lượng cho 3 khẩu phần.','',25,'easy',3,'1. Làm sạch và sơ chế nguyên liệu; trải gia vị thơm như gừng, sả hoặc hành nếu có. 2. Đun sôi nước trong xửng hấp, đặt thực phẩm vào đĩa chịu nhiệt. 3. Hấp đến khi nguyên liệu chín hoàn toàn; hải sản vừa chín tới, thịt gia cầm không còn phần sống. 4. Pha phần nước chấm từ gia vị có sẵn và dùng nóng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Tôm hấp sả' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Tôm xào măng tây'),2,31))::uuid,now(),false,'Tôm xào măng tây','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Tôm sú, Măng tây. Định lượng cho 2 khẩu phần.','',25,'easy',2,'1. Rửa sạch, để ráo và cắt các nguyên liệu thành miếng vừa ăn; để riêng đạm và rau. 2. Làm nóng dầu, phi thơm hành hoặc tỏi nếu có; xào phần đạm đến khi chín. 3. Cho rau củ vào, đảo nhanh ở lửa vừa-lớn để rau vừa chín; nêm với gia vị đã định lượng. 4. Kiểm tra độ chín của đạm, bày ra đĩa và dùng nóng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Tôm xào măng tây' AND NOT r.is_deleted);
