INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Nghêu hấp sả'),2,31))::uuid,now(),false,'Nghêu hấp sả','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Nghêu. Định lượng cho 3 khẩu phần.','',25,'easy',3,'1. Làm sạch và sơ chế nguyên liệu; trải gia vị thơm như gừng, sả hoặc hành nếu có. 2. Đun sôi nước trong xửng hấp, đặt thực phẩm vào đĩa chịu nhiệt. 3. Hấp đến khi nguyên liệu chín hoàn toàn; hải sản vừa chín tới, thịt gia cầm không còn phần sống. 4. Pha phần nước chấm từ gia vị có sẵn và dùng nóng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Nghêu hấp sả' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Hàu nướng phô mai'),2,31))::uuid,now(),false,'Hàu nướng phô mai','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Hàu, Phô mai mozzarella. Định lượng cho 3 khẩu phần.','',30,'medium',3,'1. Sơ chế nguyên liệu, ướp với phần gia vị có trong công thức khoảng 10–15 phút. 2. Làm nóng lò ở khoảng 190°C hoặc chuẩn bị nồi chiên không dầu; đặt thực phẩm lên khay. 3. Nướng đến khi chín, lật hoặc đảo giữa chừng nếu cần, điều chỉnh thời gian theo kích thước thực tế. 4. Kiểm tra thịt gia cầm chín hoàn toàn, bày cùng phần rau đi kèm.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Hàu nướng phô mai' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Cá bống kho nghệ'),2,31))::uuid,now(),false,'Cá bống kho nghệ','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Cá bống. Định lượng cho 3 khẩu phần.','',45,'medium',3,'1. Rửa sạch, sơ chế nguyên liệu; ướp cùng hành, nước mắm hoặc gia vị trong 10–15 phút. 2. Làm nóng nồi, đảo săn nguyên liệu chính. 3. Thêm lượng nước hoặc nước dừa đã liệt kê nếu có; đậy nắp, kho lửa nhỏ đến khi chín mềm và nước sệt vừa. 4. Nếm lại trước khi dùng; món kho thịt phải chín kỹ.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Cá bống kho nghệ' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Tôm đậu hũ sốt cà'),2,31))::uuid,now(),false,'Tôm đậu hũ sốt cà','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Tôm thẻ, Đậu hũ trắng, Cà chua. Định lượng cho 3 khẩu phần.','',30,'easy',3,'1. Rửa sạch, thái hoặc cắt nguyên liệu theo kích thước vừa ăn. 2. Làm chín phần đạm trước trên chảo; lấy ra riêng nếu cần. 3. Xào thơm hành, tỏi rồi đun cà chua, nấm hoặc thành phần tạo sốt đến khi mềm; thêm ít nước nếu quá đặc. 4. Cho nguyên liệu chính trở lại, nấu đến khi chín hoàn toàn và sốt bám đều.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Tôm đậu hũ sốt cà' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Cá hồi sốt miso'),2,31))::uuid,now(),false,'Cá hồi sốt miso','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Cá hồi, Bông cải xanh. Định lượng cho 2 khẩu phần.','',35,'medium',2,'1. Sơ chế nguyên liệu, ướp với phần gia vị có trong công thức khoảng 10–15 phút. 2. Làm nóng lò ở khoảng 190°C hoặc chuẩn bị nồi chiên không dầu; đặt thực phẩm lên khay. 3. Nướng đến khi chín, lật hoặc đảo giữa chừng nếu cần, điều chỉnh thời gian theo kích thước thực tế. 4. Kiểm tra thịt gia cầm chín hoàn toàn, bày cùng phần rau đi kèm.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Cá hồi sốt miso' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Cá cơm tươi chiên giòn'),2,31))::uuid,now(),false,'Cá cơm tươi chiên giòn','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Cá cơm tươi, Bột gạo, Bột bắp. Định lượng cho 3 khẩu phần.','',25,'easy',3,'1. Sơ chế và cắt nhỏ phần nguyên liệu cần thiết. 2. Làm nóng lượng dầu trong công thức; chiên nguyên liệu chính từng mẻ đến khi chín và có màu vàng vừa. 3. Với cơm hoặc rau kèm, đảo đều trên chảo và nêm gia vị; với cá, để ráo dầu trước khi dùng. 4. Dùng nóng, kiểm tra kỹ độ chín đối với trứng và hải sản.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Cá cơm tươi chiên giòn' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Đậu hũ kho nấm rơm'),2,31))::uuid,now(),false,'Đậu hũ kho nấm rơm','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Đậu hũ trắng, Nấm rơm. Định lượng cho 3 khẩu phần.','',30,'easy',3,'1. Rửa sạch, sơ chế nguyên liệu; ướp cùng hành, nước mắm hoặc gia vị trong 10–15 phút. 2. Làm nóng nồi, đảo săn nguyên liệu chính. 3. Thêm lượng nước hoặc nước dừa đã liệt kê nếu có; đậy nắp, kho lửa nhỏ đến khi chín mềm và nước sệt vừa. 4. Nếm lại trước khi dùng; món kho thịt phải chín kỹ.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Đậu hũ kho nấm rơm' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Đậu hũ sốt cà chua'),2,31))::uuid,now(),false,'Đậu hũ sốt cà chua','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Đậu hũ trắng, Cà chua. Định lượng cho 2 khẩu phần.','',25,'easy',2,'1. Rửa sạch, thái hoặc cắt nguyên liệu theo kích thước vừa ăn. 2. Làm chín phần đạm trước trên chảo; lấy ra riêng nếu cần. 3. Xào thơm hành, tỏi rồi đun cà chua, nấm hoặc thành phần tạo sốt đến khi mềm; thêm ít nước nếu quá đặc. 4. Cho nguyên liệu chính trở lại, nấu đến khi chín hoàn toàn và sốt bám đều.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Đậu hũ sốt cà chua' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Đậu hũ non hấp nấm'),2,31))::uuid,now(),false,'Đậu hũ non hấp nấm','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Đậu hũ non, Nấm hương tươi. Định lượng cho 2 khẩu phần.','',25,'easy',2,'1. Làm sạch và sơ chế nguyên liệu; trải gia vị thơm như gừng, sả hoặc hành nếu có. 2. Đun sôi nước trong xửng hấp, đặt thực phẩm vào đĩa chịu nhiệt. 3. Hấp đến khi nguyên liệu chín hoàn toàn; hải sản vừa chín tới, thịt gia cầm không còn phần sống. 4. Pha phần nước chấm từ gia vị có sẵn và dùng nóng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Đậu hũ non hấp nấm' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Đậu hũ chiên sả ớt'),2,31))::uuid,now(),false,'Đậu hũ chiên sả ớt','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Đậu hũ trắng. Định lượng cho 3 khẩu phần.','',30,'easy',3,'1. Sơ chế và cắt nhỏ phần nguyên liệu cần thiết. 2. Làm nóng lượng dầu trong công thức; chiên nguyên liệu chính từng mẻ đến khi chín và có màu vàng vừa. 3. Với cơm hoặc rau kèm, đảo đều trên chảo và nêm gia vị; với cá, để ráo dầu trước khi dùng. 4. Dùng nóng, kiểm tra kỹ độ chín đối với trứng và hải sản.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Đậu hũ chiên sả ớt' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Nấm đùi gà áp chảo'),2,31))::uuid,now(),false,'Nấm đùi gà áp chảo','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Nấm đùi gà. Định lượng cho 2 khẩu phần.','',25,'easy',2,'1. Sơ chế, thấm khô nguyên liệu chính; ướp nhẹ với gia vị trong công thức. 2. Làm nóng chảo cùng dầu, áp chảo từng mặt đến khi chín phù hợp; tránh để quá lửa. 3. Làm chín rau củ ăn kèm trên chảo hoặc hấp riêng. 4. Rưới phần sốt hoặc nước cốt chanh nếu có, chia đều theo khẩu phần.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Nấm đùi gà áp chảo' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Đậu gà xào rau củ'),2,31))::uuid,now(),false,'Đậu gà xào rau củ','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Đậu gà nấu chín, Ớt chuông đỏ, Bí ngòi. Định lượng cho 2 khẩu phần.','',25,'easy',2,'1. Rửa sạch, để ráo và cắt các nguyên liệu thành miếng vừa ăn; để riêng đạm và rau. 2. Làm nóng dầu, phi thơm hành hoặc tỏi nếu có; xào phần đạm đến khi chín. 3. Cho rau củ vào, đảo nhanh ở lửa vừa-lớn để rau vừa chín; nêm với gia vị đã định lượng. 4. Kiểm tra độ chín của đạm, bày ra đĩa và dùng nóng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Đậu gà xào rau củ' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Đậu lăng sốt cà chua'),2,31))::uuid,now(),false,'Đậu lăng sốt cà chua','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Đậu lăng nấu chín, Cà chua, Hành tây. Định lượng cho 3 khẩu phần.','',30,'easy',3,'1. Rửa sạch, thái hoặc cắt nguyên liệu theo kích thước vừa ăn. 2. Làm chín phần đạm trước trên chảo; lấy ra riêng nếu cần. 3. Xào thơm hành, tỏi rồi đun cà chua, nấm hoặc thành phần tạo sốt đến khi mềm; thêm ít nước nếu quá đặc. 4. Cho nguyên liệu chính trở lại, nấu đến khi chín hoàn toàn và sốt bám đều.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Đậu lăng sốt cà chua' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Bí đỏ nướng hạt bí'),2,31))::uuid,now(),false,'Bí đỏ nướng hạt bí','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Bí đỏ, Hạt bí. Định lượng cho 2 khẩu phần.','',35,'easy',2,'1. Sơ chế nguyên liệu, ướp với phần gia vị có trong công thức khoảng 10–15 phút. 2. Làm nóng lò ở khoảng 190°C hoặc chuẩn bị nồi chiên không dầu; đặt thực phẩm lên khay. 3. Nướng đến khi chín, lật hoặc đảo giữa chừng nếu cần, điều chỉnh thời gian theo kích thước thực tế. 4. Kiểm tra thịt gia cầm chín hoàn toàn, bày cùng phần rau đi kèm.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Bí đỏ nướng hạt bí' AND NOT r.is_deleted);
