INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Cải thìa sốt nấm'),2,31))::uuid,now(),false,'Cải thìa sốt nấm','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Cải thìa, Nấm hương tươi. Định lượng cho 2 khẩu phần.','',25,'easy',2,'1. Rửa sạch, thái hoặc cắt nguyên liệu theo kích thước vừa ăn. 2. Làm chín phần đạm trước trên chảo; lấy ra riêng nếu cần. 3. Xào thơm hành, tỏi rồi đun cà chua, nấm hoặc thành phần tạo sốt đến khi mềm; thêm ít nước nếu quá đặc. 4. Cho nguyên liệu chính trở lại, nấu đến khi chín hoàn toàn và sốt bám đều.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Cải thìa sốt nấm' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Cà ri khoai tây đậu gà'),2,31))::uuid,now(),false,'Cà ri khoai tây đậu gà','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Đậu gà nấu chín, Khoai tây, Cà chua. Định lượng cho 3 khẩu phần.','',40,'medium',3,'1. Sơ chế nguyên liệu, cắt thịt hoặc khoai thành miếng vừa. 2. Phi thơm hành và bột cà ri cùng ít dầu, đảo nguyên liệu chính cho săn. 3. Thêm nước cốt dừa và nước vừa đủ, nấu lửa nhỏ cho đến khi các thành phần chín mềm. 4. Nêm lại, chia đều theo khẩu phần, ăn cùng cơm nếu có trong định lượng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Cà ri khoai tây đậu gà' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Rau củ nướng thập cẩm'),2,31))::uuid,now(),false,'Rau củ nướng thập cẩm','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Cà rốt, Bí đỏ, Bí ngòi. Định lượng cho 3 khẩu phần.','',40,'easy',3,'1. Sơ chế nguyên liệu, ướp với phần gia vị có trong công thức khoảng 10–15 phút. 2. Làm nóng lò ở khoảng 190°C hoặc chuẩn bị nồi chiên không dầu; đặt thực phẩm lên khay. 3. Nướng đến khi chín, lật hoặc đảo giữa chừng nếu cần, điều chỉnh thời gian theo kích thước thực tế. 4. Kiểm tra thịt gia cầm chín hoàn toàn, bày cùng phần rau đi kèm.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Rau củ nướng thập cẩm' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Nấm kim châm cuộn đậu hũ ky'),2,31))::uuid,now(),false,'Nấm kim châm cuộn đậu hũ ky','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Tàu hũ ky, Nấm kim châm. Định lượng cho 3 khẩu phần.','',35,'medium',3,'1. Sơ chế, thấm khô nguyên liệu chính; ướp nhẹ với gia vị trong công thức. 2. Làm nóng chảo cùng dầu, áp chảo từng mặt đến khi chín phù hợp; tránh để quá lửa. 3. Làm chín rau củ ăn kèm trên chảo hoặc hấp riêng. 4. Rưới phần sốt hoặc nước cốt chanh nếu có, chia đều theo khẩu phần.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Nấm kim châm cuộn đậu hũ ky' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Đậu hũ xào đậu cove'),2,31))::uuid,now(),false,'Đậu hũ xào đậu cove','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Đậu hũ trắng, Đậu cove, Cà rốt. Định lượng cho 2 khẩu phần.','',25,'easy',2,'1. Rửa sạch, để ráo và cắt các nguyên liệu thành miếng vừa ăn; để riêng đạm và rau. 2. Làm nóng dầu, phi thơm hành hoặc tỏi nếu có; xào phần đạm đến khi chín. 3. Cho rau củ vào, đảo nhanh ở lửa vừa-lớn để rau vừa chín; nêm với gia vị đã định lượng. 4. Kiểm tra độ chín của đạm, bày ra đĩa và dùng nóng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Đậu hũ xào đậu cove' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Bánh mì đậu hũ áp chảo'),2,31))::uuid,now(),false,'Bánh mì đậu hũ áp chảo','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Bánh mì nguyên cám, Đậu hũ trắng, Rau xà lách. Định lượng cho 2 khẩu phần.','',25,'easy',2,'1. Sơ chế, thấm khô nguyên liệu chính; ướp nhẹ với gia vị trong công thức. 2. Làm nóng chảo cùng dầu, áp chảo từng mặt đến khi vàng đều; tránh để quá lửa. 3. Làm chín rau củ ăn kèm trên chảo hoặc hấp riêng. 4. Rưới phần sốt hoặc nước cốt chanh nếu có, chia đều theo khẩu phần.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Bánh mì đậu hũ áp chảo' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Canh chua cá lóc'),2,31))::uuid,now(),false,'Canh chua cá lóc','Món nước ấm, có thể chia thành các khẩu phần gia đình; thành phần chính gồm Cá lóc, Cà chua, Dứa. Định lượng cho 3 khẩu phần.','',40,'medium',3,'1. Rửa sạch rau củ và sơ chế cá, thịt hoặc hải sản. 2. Đun sôi lượng nước đã định lượng; cho nguyên liệu lâu chín vào trước, hớt bọt khi cần. 3. Thêm rau củ, nêm nước mắm, me hoặc muối theo bảng nguyên liệu; nấu đến khi chín vừa. 4. Thêm rau thơm ở cuối và dùng nóng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Canh chua cá lóc' AND NOT r.is_deleted);
