INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Canh rong biển thịt băm'),2,31))::uuid,now(),false,'Canh rong biển thịt băm','Món nước ấm, có thể chia thành các khẩu phần gia đình; thành phần chính gồm Rong biển khô, Thịt heo xay, Đậu hũ non. Định lượng cho 3 khẩu phần.','',25,'easy',3,'1. Rửa sạch rau củ và sơ chế cá, thịt hoặc hải sản. 2. Đun sôi lượng nước đã định lượng; cho nguyên liệu lâu chín vào trước, hớt bọt khi cần. 3. Thêm rau củ, nêm nước mắm, me hoặc muối theo bảng nguyên liệu; nấu đến khi chín vừa. 4. Thêm rau thơm ở cuối và dùng nóng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Canh rong biển thịt băm' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Canh sườn củ cải'),2,31))::uuid,now(),false,'Canh sườn củ cải','Món nước ấm, có thể chia thành các khẩu phần gia đình; thành phần chính gồm Sườn non heo, Củ cải trắng, Cà rốt. Định lượng cho 3 khẩu phần.','',55,'medium',3,'1. Sơ chế nguyên liệu, xử lý và ngâm đậu khô trước nếu cần (thời gian ngâm không tính vào thời gian nấu). 2. Đun phần nước hoặc nước dùng, cho nguyên liệu lâu chín vào trước. 3. Hầm lửa nhỏ cho đến khi thịt hoặc đậu mềm, tiếp đó thêm rau củ để tránh nát. 4. Nêm gia vị và chia khẩu phần khi còn nóng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Canh sườn củ cải' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Cháo gà nấm hương'),2,31))::uuid,now(),false,'Cháo gà nấm hương','Món nước ấm, có thể chia thành các khẩu phần gia đình; thành phần chính gồm Gạo tẻ, Thịt gà xé chín, Nấm hương tươi. Định lượng cho 3 khẩu phần.','',45,'medium',3,'1. Vo gạo hoặc chuẩn bị yến mạch; sơ chế thịt, cá, rau và nấm. 2. Đun gạo với nước hoặc nước dùng đến khi hạt nở mềm, khuấy chống dính. 3. Cho nguyên liệu đạm đã làm sạch vào nấu chín kỹ, sau đó thêm rau và gia vị. 4. Kiểm tra kỹ xương cá nếu có, chia cháo theo khẩu phần.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Cháo gà nấm hương' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Cháo thịt băm cà rốt'),2,31))::uuid,now(),false,'Cháo thịt băm cà rốt','Món nước ấm, có thể chia thành các khẩu phần gia đình; thành phần chính gồm Gạo tẻ, Thịt heo xay, Cà rốt. Định lượng cho 3 khẩu phần.','',40,'easy',3,'1. Vo gạo hoặc chuẩn bị yến mạch; sơ chế thịt, cá, rau và nấm. 2. Đun gạo với nước hoặc nước dùng đến khi hạt nở mềm, khuấy chống dính. 3. Cho nguyên liệu đạm đã làm sạch vào nấu chín kỹ, sau đó thêm rau và gia vị. 4. Kiểm tra kỹ xương cá nếu có, chia cháo theo khẩu phần.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Cháo thịt băm cà rốt' AND NOT r.is_deleted);
