INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Cháo yến mạch trứng'),2,31))::uuid,now(),false,'Cháo yến mạch trứng','Món nước ấm, có thể chia thành các khẩu phần gia đình; thành phần chính gồm Yến mạch cán, Trứng gà, Cà rốt. Định lượng cho 2 khẩu phần.','',20,'easy',2,'1. Vo gạo hoặc chuẩn bị yến mạch; sơ chế thịt, cá, rau và nấm. 2. Đun gạo với nước hoặc nước dùng đến khi hạt nở mềm, khuấy chống dính. 3. Cho nguyên liệu đạm đã làm sạch vào nấu chín kỹ, sau đó thêm rau và gia vị. 4. Kiểm tra kỹ xương cá nếu có, chia cháo theo khẩu phần.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Cháo yến mạch trứng' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Phở bò tái gia đình'),2,31))::uuid,now(),false,'Phở bò tái gia đình','Món nước ấm, có thể chia thành các khẩu phần gia đình; thành phần chính gồm Bánh phở tươi, Thịt bò phi lê, Xương ống heo. Định lượng cho 4 khẩu phần.','',75,'hard',4,'1. Sơ chế nguyên liệu; với xương dùng nấu nước dùng, chần sơ để giảm bọt. 2. Ninh nước dùng cùng gừng, hành và gia vị thơm; lọc cho trong và nêm vừa. 3. Chần bánh phở; đảm bảo thịt bò hoặc thịt gà chín đến mức an toàn trước khi phục vụ. 4. Xếp bánh phở, thịt, hành và rau thơm, chan nước dùng nóng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Phở bò tái gia đình' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Phở gà đơn giản'),2,31))::uuid,now(),false,'Phở gà đơn giản','Món nước ấm, có thể chia thành các khẩu phần gia đình; thành phần chính gồm Bánh phở tươi, Thịt gà xé chín, Hành tây. Định lượng cho 3 khẩu phần.','',50,'medium',3,'1. Sơ chế nguyên liệu; với xương dùng nấu nước dùng, chần sơ để giảm bọt. 2. Ninh nước dùng cùng gừng, hành và gia vị thơm; lọc cho trong và nêm vừa. 3. Chần bánh phở; đảm bảo thịt bò hoặc thịt gà chín đến mức an toàn trước khi phục vụ. 4. Xếp bánh phở, thịt, hành và rau thơm, chan nước dùng nóng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Phở gà đơn giản' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Bún cá rô phi'),2,31))::uuid,now(),false,'Bún cá rô phi','Món nước ấm, có thể chia thành các khẩu phần gia đình; thành phần chính gồm Bún tươi, Cá rô phi, Cà chua. Định lượng cho 3 khẩu phần.','',45,'medium',3,'1. Sơ chế cá, tôm, thịt và rau; nấu nước dùng từ nguyên liệu đã định lượng. 2. Thêm phần đạm vào nước dùng, nấu chín kỹ; cho rau củ và nêm gia vị sau. 3. Chần bún nhanh bằng nước sạch nóng, để ráo. 4. Xếp bún vào tô, thêm topping và chan nước dùng nóng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Bún cá rô phi' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Hủ tiếu tôm thịt'),2,31))::uuid,now(),false,'Hủ tiếu tôm thịt','Món nước ấm, có thể chia thành các khẩu phần gia đình; thành phần chính gồm Hủ tiếu tươi, Tôm thẻ, Thịt heo nạc thăn. Định lượng cho 3 khẩu phần.','',45,'medium',3,'1. Chuẩn bị nước dùng, sơ chế tôm, thịt và rau. 2. Nấu chín thịt và tôm trong nước dùng, nêm vừa. 3. Chần hủ tiếu đến độ mềm mong muốn; trụng rau ăn kèm nếu cần. 4. Cho hủ tiếu vào tô, thêm topping và chan nước dùng nóng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Hủ tiếu tôm thịt' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Bún riêu cua đơn giản'),2,31))::uuid,now(),false,'Bún riêu cua đơn giản','Món nước ấm, có thể chia thành các khẩu phần gia đình; thành phần chính gồm Bún tươi, Cua đồng, Trứng gà. Định lượng cho 4 khẩu phần.','',55,'hard',4,'1. Sơ chế cá, tôm, thịt và rau; nấu nước dùng từ nguyên liệu đã định lượng. 2. Thêm phần đạm vào nước dùng, nấu chín kỹ; cho rau củ và nêm gia vị sau. 3. Chần bún nhanh bằng nước sạch nóng, để ráo. 4. Xếp bún vào tô, thêm topping và chan nước dùng nóng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Bún riêu cua đơn giản' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Miến gà nấm'),2,31))::uuid,now(),false,'Miến gà nấm','Món nước ấm, có thể chia thành các khẩu phần gia đình; thành phần chính gồm Miến dong khô, Thịt gà xé chín, Nấm hương tươi. Định lượng cho 3 khẩu phần.','',35,'easy',3,'1. Ngâm miến trong nước mát cho mềm, cắt ngắn nếu cần; sơ chế các thành phần còn lại. 2. Đun nóng nước dùng với nấm, gừng và nguyên liệu đạm đến khi chín. 3. Cho miến vào nấu ngắn để sợi vừa mềm, nêm gia vị. 4. Rắc hành và dùng ngay.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Miến gà nấm' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Mì Ý sốt bò bằm'),2,31))::uuid,now(),false,'Mì Ý sốt bò bằm','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Mì Ý khô, Thịt bò xay, Cà chua. Định lượng cho 3 khẩu phần.','',45,'medium',3,'1. Luộc mì theo hướng dẫn loại mì đang dùng, để ráo và giữ lại ít nước luộc nếu cần. 2. Sơ chế, làm chín thịt, nấm và rau trên chảo. 3. Thêm cà chua hoặc gia vị làm sốt; đảo cùng mì cho thấm đều và kiểm tra độ chín. 4. Dùng nóng, thêm phô mai nếu có.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Mì Ý sốt bò bằm' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Mì trứng xào rau nấm'),2,31))::uuid,now(),false,'Mì trứng xào rau nấm','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Mì trứng khô, Nấm bào ngư, Cải thìa. Định lượng cho 3 khẩu phần.','',30,'easy',3,'1. Luộc mì theo hướng dẫn loại mì đang dùng, để ráo và giữ lại ít nước luộc nếu cần. 2. Sơ chế, làm chín thịt, nấm và rau trên chảo. 3. Thêm cà chua hoặc gia vị làm sốt; đảo cùng mì cho thấm đều và kiểm tra độ chín. 4. Dùng nóng, thêm phô mai nếu có.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Mì trứng xào rau nấm' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Bún thịt nướng rau sống'),2,31))::uuid,now(),false,'Bún thịt nướng rau sống','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Bún tươi, Thịt heo nạc vai, Rau xà lách. Định lượng cho 3 khẩu phần.','',45,'medium',3,'1. Ướp thịt cùng sả, tỏi và gia vị; nướng hoặc áp chảo đến khi chín kỹ. 2. Rửa rau sống bằng nước sạch và để ráo; chần bún rồi để nguội bớt. 3. Pha nước trộn từ nước mắm, đường, chanh hoặc gia vị đã định lượng. 4. Xếp bún, thịt, rau, chan nước trộn ngay trước khi ăn.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Bún thịt nướng rau sống' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Bún tôm rau muống'),2,31))::uuid,now(),false,'Bún tôm rau muống','Món nước ấm, có thể chia thành các khẩu phần gia đình; thành phần chính gồm Bún tươi, Tôm thẻ, Rau muống. Định lượng cho 3 khẩu phần.','',35,'easy',3,'1. Sơ chế cá, tôm, thịt và rau; nấu nước dùng từ nguyên liệu đã định lượng. 2. Thêm phần đạm vào nước dùng, nấu chín kỹ; cho rau củ và nêm gia vị sau. 3. Chần bún nhanh bằng nước sạch nóng, để ráo. 4. Xếp bún vào tô, thêm topping và chan nước dùng nóng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Bún tôm rau muống' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Gỏi gà bắp cải'),2,31))::uuid,now(),false,'Gỏi gà bắp cải','Món trộn hoặc cuốn với các thành phần tươi, thích hợp thay đổi thực đơn hằng ngày; thành phần chính gồm Thịt gà xé chín, Bắp cải, Cà rốt. Định lượng cho 3 khẩu phần.','',25,'easy',3,'1. Rửa thật sạch rau và trái cây, cắt hoặc bào sợi; chế biến chín hoàn toàn phần thịt, tôm hoặc cá nếu có. 2. Pha nước trộn với chanh, nước mắm và đường theo định lượng, nếm cân bằng chua-mặn-ngọt. 3. Trộn đều phần chính với nước trộn ngay trước khi ăn. 4. Rắc lạc hoặc rau thơm nếu có và phục vụ ngay.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Gỏi gà bắp cải' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Gỏi cuốn tôm thịt'),2,31))::uuid,now(),false,'Gỏi cuốn tôm thịt','Món trộn hoặc cuốn với các thành phần tươi, thích hợp thay đổi thực đơn hằng ngày; thành phần chính gồm Bánh tráng gạo, Tôm thẻ, Thịt heo nạc thăn. Định lượng cho 3 khẩu phần.','',35,'medium',3,'1. Luộc hoặc hấp chín phần thịt, tôm chưa chín; rửa sạch rau ăn sống và để ráo. 2. Làm mềm bánh tráng theo hướng dẫn trên bao bì. 3. Đặt lượng nhân vừa phải, cuốn chặt tay; tránh để cuốn quá lâu làm bánh mềm nhũn. 4. Pha nước chấm từ thành phần đã cho, ăn ngay sau khi cuốn.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Gỏi cuốn tôm thịt' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Gỏi đu đủ tôm'),2,31))::uuid,now(),false,'Gỏi đu đủ tôm','Món trộn hoặc cuốn với các thành phần tươi, thích hợp thay đổi thực đơn hằng ngày; thành phần chính gồm Đu đủ xanh, Tôm sú, Cà rốt. Định lượng cho 3 khẩu phần.','',25,'easy',3,'1. Rửa thật sạch rau và trái cây, cắt hoặc bào sợi; chế biến chín hoàn toàn phần thịt, tôm hoặc cá nếu có. 2. Pha nước trộn với chanh, nước mắm và đường theo định lượng, nếm cân bằng chua-mặn-ngọt. 3. Trộn đều phần chính với nước trộn ngay trước khi ăn. 4. Rắc lạc hoặc rau thơm nếu có và phục vụ ngay.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Gỏi đu đủ tôm' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Gỏi ngó sen tôm'),2,31))::uuid,now(),false,'Gỏi ngó sen tôm','Món trộn hoặc cuốn với các thành phần tươi, thích hợp thay đổi thực đơn hằng ngày; thành phần chính gồm Ngó sen, Tôm thẻ, Cà rốt. Định lượng cho 3 khẩu phần.','',30,'medium',3,'1. Rửa thật sạch rau và trái cây, cắt hoặc bào sợi; chế biến chín hoàn toàn phần thịt, tôm hoặc cá nếu có. 2. Pha nước trộn với chanh, nước mắm và đường theo định lượng, nếm cân bằng chua-mặn-ngọt. 3. Trộn đều phần chính với nước trộn ngay trước khi ăn. 4. Rắc lạc hoặc rau thơm nếu có và phục vụ ngay.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Gỏi ngó sen tôm' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Salad gà bơ'),2,31))::uuid,now(),false,'Salad gà bơ','Món trộn hoặc cuốn với các thành phần tươi, thích hợp thay đổi thực đơn hằng ngày; thành phần chính gồm Thịt gà xé chín, Bơ quả, Rau xà lách. Định lượng cho 2 khẩu phần.','',20,'easy',2,'1. Rửa sạch và để ráo rau quả; nấu chín phần thịt, cá, trứng hoặc ngũ cốc chưa chín trong công thức, để nguội vừa. 2. Cắt các thành phần thành miếng vừa ăn. 3. Đánh đều dầu ô liu, chanh hoặc giấm, sữa chua cùng gia vị theo danh sách. 4. Trộn đều trước khi dùng, bảo quản lạnh nếu chưa ăn ngay.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Salad gà bơ' AND NOT r.is_deleted);
