INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Sandwich trứng phô mai'),2,31))::uuid,now(),false,'Sandwich trứng phô mai','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Bánh mì sandwich, Trứng gà, Phô mai cheddar. Định lượng cho 2 khẩu phần.','',15,'easy',2,'1. Rửa sạch, để ráo và thái mỏng phần rau; nấu chín hoàn toàn trứng, cá hoặc thịt chưa chín. 2. Nướng hoặc làm nóng bánh mì nhẹ cho giòn. 3. Chuẩn bị sốt từ nguyên liệu đã liệt kê, phết lượng vừa phải. 4. Xếp nhân, rau và gia vị vào bánh, dùng ngay.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Sandwich trứng phô mai' AND NOT r.is_deleted);
