INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Xôi đậu xanh gia đình'),2,31))::uuid,now(),false,'Xôi đậu xanh gia đình','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Gạo nếp, Đậu xanh cà vỏ. Định lượng cho 4 khẩu phần.','',55,'medium',4,'1. Vo gạo nếp và ngâm trước khi nấu khoảng 4–6 giờ (thời gian ngâm không nằm trong thời gian nấu). 2. Hấp gạo nếp cùng đậu đã xử lý đến khi chín dẻo, đảo một lần cho đều. 3. Chế biến chín nhân gà hoặc phi hành nếu có, nêm vừa. 4. Chia xôi và topping theo khẩu phần, dùng nóng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Xôi đậu xanh gia đình' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Xôi gà xé'),2,31))::uuid,now(),false,'Xôi gà xé','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Gạo nếp, Thịt gà xé chín. Định lượng cho 4 khẩu phần.','',55,'medium',4,'1. Vo gạo nếp và ngâm trước khi nấu khoảng 4–6 giờ (thời gian ngâm không nằm trong thời gian nấu). 2. Hấp gạo nếp cùng đậu đã xử lý đến khi chín dẻo, đảo một lần cho đều. 3. Chế biến chín nhân gà hoặc phi hành nếu có, nêm vừa. 4. Chia xôi và topping theo khẩu phần, dùng nóng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Xôi gà xé' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Khoai lang luộc trứng'),2,31))::uuid,now(),false,'Khoai lang luộc trứng','Món ăn gia đình, thực hiện bằng nguyên liệu phổ biến; thành phần chính gồm Khoai lang vàng, Trứng gà, Dưa leo. Định lượng cho 2 khẩu phần.','',25,'easy',2,'1. Rửa sạch, cắt nguyên liệu theo kích thước hợp lý. 2. Đun sôi nước, luộc củ trước đến khi mềm; luộc trứng chín kỹ nếu có. 3. Vớt để ráo, thái hoặc bóc vỏ trước khi chia khẩu phần. 4. Dùng cùng phần rau và gia vị đã liệt kê.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Khoai lang luộc trứng' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Yến mạch sữa chuối'),2,31))::uuid,now(),false,'Yến mạch sữa chuối','Món ăn nhẹ hoặc tráng miệng chế biến tại nhà; thành phần chính gồm Yến mạch cán, Sữa tươi không đường, Chuối tiêu. Định lượng cho 2 khẩu phần.','',10,'easy',2,'1. Cho yến mạch vào hộp sạch, trộn với sữa theo định lượng. 2. Thêm hạt chia và mật ong, khuấy đều rồi để lạnh qua đêm hoặc ít nhất 4 giờ (thời gian ngâm không tính trong thời gian thao tác). 3. Cắt chuối hoặc trái cây khi sắp ăn. 4. Chia thành hai khẩu phần, giữ lạnh cho đến khi dùng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Yến mạch sữa chuối' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Yến mạch táo quế'),2,31))::uuid,now(),false,'Yến mạch táo quế','Món ăn nhẹ hoặc tráng miệng chế biến tại nhà; thành phần chính gồm Yến mạch cán, Sữa tươi không đường, Táo. Định lượng cho 2 khẩu phần.','',18,'easy',2,'1. Cắt trái cây thành miếng nhỏ, chuẩn bị yến mạch và sữa. 2. Đun yến mạch với sữa ở lửa nhỏ, khuấy đến khi sánh. 3. Thêm trái cây và gia vị thơm, nấu ngắn để không nát. 4. Tắt bếp, thêm mật ong và các loại hạt nếu có rồi chia khẩu phần.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Yến mạch táo quế' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Sữa chua trái cây hạt'),2,31))::uuid,now(),false,'Sữa chua trái cây hạt','Món ăn nhẹ hoặc tráng miệng chế biến tại nhà; thành phần chính gồm Sữa chua không đường, Dâu tây, Việt quất. Định lượng cho 2 khẩu phần.','',10,'easy',2,'1. Rửa sạch và để ráo tất cả trái cây. 2. Cắt trái cây thành miếng vừa ăn, trộn cùng sữa chua. 3. Thêm các loại hạt ngay trước khi dùng để giữ độ giòn. 4. Chia khẩu phần và giữ lạnh nếu chưa ăn.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Sữa chua trái cây hạt' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Sinh tố chuối bơ'),2,31))::uuid,now(),false,'Sinh tố chuối bơ','Món ăn nhẹ hoặc tráng miệng chế biến tại nhà; thành phần chính gồm Chuối tiêu, Bơ quả, Sữa tươi không đường. Định lượng cho 2 khẩu phần.','',10,'easy',2,'1. Rửa và gọt vỏ trái cây, bỏ hạt, cắt miếng. 2. Cho trái cây, phần sữa hoặc nước dừa đã định lượng vào máy xay. 3. Xay đến khi mịn; điều chỉnh độ sánh bằng một ít nước nếu cần. 4. Dùng ngay, không thay thế một bữa ăn đầy đủ chỉ bằng sinh tố nếu nhu cầu dinh dưỡng chưa được đáp ứng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Sinh tố chuối bơ' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Sinh tố xoài sữa chua'),2,31))::uuid,now(),false,'Sinh tố xoài sữa chua','Món ăn nhẹ hoặc tráng miệng chế biến tại nhà; thành phần chính gồm Xoài chín, Sữa chua không đường, Sữa tươi tách béo. Định lượng cho 2 khẩu phần.','',10,'easy',2,'1. Rửa và gọt vỏ trái cây, bỏ hạt, cắt miếng. 2. Cho trái cây, phần sữa hoặc nước dừa đã định lượng vào máy xay. 3. Xay đến khi mịn; điều chỉnh độ sánh bằng một ít nước nếu cần. 4. Dùng ngay, không thay thế một bữa ăn đầy đủ chỉ bằng sinh tố nếu nhu cầu dinh dưỡng chưa được đáp ứng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Sinh tố xoài sữa chua' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Sinh tố dứa cải bó xôi'),2,31))::uuid,now(),false,'Sinh tố dứa cải bó xôi','Món ăn nhẹ hoặc tráng miệng chế biến tại nhà; thành phần chính gồm Dứa, Cải bó xôi, Chuối tiêu. Định lượng cho 2 khẩu phần.','',10,'easy',2,'1. Rửa và gọt vỏ trái cây, bỏ hạt, cắt miếng. 2. Cho trái cây, phần sữa hoặc nước dừa đã định lượng vào máy xay. 3. Xay đến khi mịn; điều chỉnh độ sánh bằng một ít nước nếu cần. 4. Dùng ngay, không thay thế một bữa ăn đầy đủ chỉ bằng sinh tố nếu nhu cầu dinh dưỡng chưa được đáp ứng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Sinh tố dứa cải bó xôi' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Chè đậu xanh nước cốt dừa'),2,31))::uuid,now(),false,'Chè đậu xanh nước cốt dừa','Món ăn nhẹ hoặc tráng miệng chế biến tại nhà; thành phần chính gồm Đậu xanh cà vỏ. Định lượng cho 4 khẩu phần.','',45,'easy',4,'1. Nhặt và rửa sạch hạt hoặc đậu; ngâm đậu khô trước khi nấu nếu cần (thời gian ngâm không tính vào thời gian nấu). 2. Ninh nguyên liệu với nước đến khi mềm, vớt bọt. 3. Cho đường và lá dứa vào khi hạt đã mềm; thêm nước cốt dừa ở cuối nếu có. 4. Chia khẩu phần, dùng ấm hoặc để nguội và bảo quản lạnh.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Chè đậu xanh nước cốt dừa' AND NOT r.is_deleted);
