INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Bánh pancake yến mạch chuối'),2,31))::uuid,now(),false,'Bánh pancake yến mạch chuối','Món ăn nhẹ hoặc tráng miệng chế biến tại nhà; thành phần chính gồm Yến mạch cán, Chuối tiêu, Trứng gà. Định lượng cho 2 khẩu phần.','',25,'easy',2,'1. Xay hoặc nghiền mịn nguyên liệu làm bột; trộn với trứng và sữa trong công thức đến khi đồng nhất. 2. Làm nóng chảo chống dính, phết lớp dầu mỏng. 3. Đổ từng bánh nhỏ, lật khi mặt bánh se lại; nấu đến khi chín hoàn toàn. 4. Dùng cùng phần mật ong hoặc trái cây đã định lượng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Bánh pancake yến mạch chuối' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Trái cây trộn sữa chua'),2,31))::uuid,now(),false,'Trái cây trộn sữa chua','Món ăn nhẹ hoặc tráng miệng chế biến tại nhà; thành phần chính gồm Sữa chua Hy Lạp, Thanh long đỏ, Kiwi. Định lượng cho 3 khẩu phần.','',10,'easy',3,'1. Rửa sạch và để ráo tất cả trái cây. 2. Cắt trái cây thành miếng vừa ăn, trộn cùng sữa chua. 3. Thêm các loại hạt ngay trước khi dùng để giữ độ giòn. 4. Chia khẩu phần và giữ lạnh nếu chưa ăn.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Trái cây trộn sữa chua' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Súp bí đỏ sữa tươi'),2,31))::uuid,now(),false,'Súp bí đỏ sữa tươi','Món nước ấm, có thể chia thành các khẩu phần gia đình; thành phần chính gồm Bí đỏ, Sữa tươi không đường, Hành tây. Định lượng cho 3 khẩu phần.','',35,'easy',3,'1. Làm sạch và cắt nguyên liệu thành miếng nhỏ. 2. Đun nước dùng cùng củ, ngô hoặc bí đến khi mềm; cho thịt gà đã chín hoặc trứng nếu có vào ở giai đoạn thích hợp. 3. Xay mịn với món súp bí hoặc làm sánh với bột năng đã hòa tan nếu là súp ngô. 4. Nêm vừa, đun chín hoàn toàn và dùng nóng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Súp bí đỏ sữa tươi' AND NOT r.is_deleted);
INSERT INTO recipes (id,created_at,is_deleted,name,description,allergens,cooking_time_minutes,difficulty,serving_size,instruction_text,image_url,source_type,gradient_from,gradient_to) SELECT ('b'||substr(md5('catalog:'||'Súp ngô gà'),2,31))::uuid,now(),false,'Súp ngô gà','Món nước ấm, có thể chia thành các khẩu phần gia đình; thành phần chính gồm Ngô ngọt, Thịt gà xé chín, Trứng gà. Định lượng cho 3 khẩu phần.','',35,'easy',3,'1. Làm sạch và cắt nguyên liệu thành miếng nhỏ. 2. Đun nước dùng cùng củ, ngô hoặc bí đến khi mềm; cho thịt gà đã chín hoặc trứng nếu có vào ở giai đoạn thích hợp. 3. Xay mịn với món súp bí hoặc làm sánh với bột năng đã hòa tan nếu là súp ngô. 4. Nêm vừa, đun chín hoàn toàn và dùng nóng.',NULL,'production-catalog-v1','#EF9D1F','#FFF0DE' WHERE NOT EXISTS (SELECT 1 FROM recipes r WHERE r.name='Súp ngô gà' AND NOT r.is_deleted);
